package com.example.emplist.entity;

import jakarta.persistence.*;
import java.math.BigDecimal;

@Entity
@Table(name = "employees")
public class Employee {

    @Id
    @Column(name = "emp_id", nullable = false)
    private Integer empId;

    @Column(name = "emp_name", length = 20, nullable = false)
    private String empName;

    @Column(name = "emp_dept", length = 10)
    private String empDept;

    @Column(name = "emp_salary", precision = 9, scale = 2)
    private BigDecimal empSalary;

    @Column(name = "emp_hire_yyyy")
    private Integer empHireYyyy;

    @Column(name = "emp_hire_mm")
    private Integer empHireMm;

    @Column(name = "emp_hire_dd")
    private Integer empHireDD;

    @Column(name = "emp_age")
    private Integer empAge;

    public Employee() {}

    public Integer getEmpId() { return empId; }
    public void setEmpId(Integer empId) { this.empId = empId; }

    public String getEmpName() { return empName; }
    public void setEmpName(String empName) { this.empName = empName; }

    public String getEmpDept() { return empDept; }
    public void setEmpDept(String empDept) { this.empDept = empDept; }

    public BigDecimal getEmpSalary() { return empSalary; }
    public void setEmpSalary(BigDecimal empSalary) { this.empSalary = empSalary; }

    public Integer getEmpHireYyyy() { return empHireYyyy; }
    public void setEmpHireYyyy(Integer empHireYyyy) { this.empHireYyyy = empHireYyyy; }

    public Integer getEmpHireMm() { return empHireMm; }
    public void setEmpHireMm(Integer empHireMm) { this.empHireMm = empHireMm; }

    public Integer getEmpHireDD() { return empHireDD; }
    public void setEmpHireDD(Integer empHireDD) { this.empHireDD = empHireDD; }

    public Integer getEmpAge() { return empAge; }
    public void setEmpAge(Integer empAge) { this.empAge = empAge; }
}

