package com.example.emplist.repository;

import com.example.emplist.entity.Employee;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.stereotype.Repository;

import java.util.List;

@Repository
public interface EmployeeRepository extends JpaRepository<Employee, Integer> {

    /**
     * Returns all employees ordered by emp_id, mirroring the sequential
     * file read order from the original COBOL program.
     */
    @Query("SELECT e FROM Employee e ORDER BY e.empId ASC")
    List<Employee> findAllOrderedById();
}

