package com.example.emplist.model;

/**
 * Represents a single 80-character line in the employee listing report.
 * Mirrors the RPT-LINE / DTL-LINE / TRL-LINE structures in COBOL.
 */
public class ReportLine {

    private final String content;

    public ReportLine(String content) {
        // Enforce 80-character width exactly as the COBOL PIC X(80) does.
        if (content.length() >= 80) {
            this.content = content.substring(0, 80);
        } else {
            this.content = String.format("%-80s", content);
        }
    }

    public String getContent() { return content; }

    @Override
    public String toString() { return content; }
}

