package com.example.emplist.service;

import com.example.emplist.entity.Employee;
import com.example.emplist.model.ReportLine;
import org.springframework.stereotype.Service;

import java.math.BigDecimal;
import java.text.DecimalFormat;
import java.text.DecimalFormatSymbols;
import java.util.Locale;

/**
 * Handles all report-line formatting logic extracted from the COBOL
 * WRITE-DETAIL paragraph and working-storage line definitions.
 */
@Service
public class ReportFormatterService {

    // HDR-1 : centred title
    private static final String HDR_1 =
            String.format("%-80s", "                     EMPLOYEE MASTER LISTING");

    // HDR-2 : column headers matching COBOL FILLER widths
    //   ID(7) + NAME(21) + DEPARTMENT(11) + SALARY(15) + HIRE DATE(12) + AGE(3)
    private static final String HDR_2 =
            String.format("%-7s%-21s%-11s%-15s%-12s%-3s",
                    "ID", "NAME", "DEPARTMENT", "      SALARY", "HIRE DATE", "AGE");

    // HDR-3 : 80 dashes (ALL "-")
    private static final String HDR_3 = "-".repeat(80);

    /**
     * Salary picture: Z,ZZZ,ZZ9.99
     * Suppresses leading zeros, uses comma grouping, two decimal places.
     */
    private static final DecimalFormat SALARY_FORMAT;
    static {
        DecimalFormatSymbols sym = new DecimalFormatSymbols(Locale.US);
        SALARY_FORMAT = new DecimalFormat("#,##0.00", sym);
        // The COBOL picture Z,ZZZ,ZZ9.99 produces at most 10 chars before decimal
        // e.g. 9,999,999.99 – we rely on the format to match.
    }

    public ReportLine header1() {
        return new ReportLine(HDR_1);
    }

    public ReportLine header2() {
        return new ReportLine(HDR_2);
    }

    public ReportLine header3() {
        return new ReportLine(HDR_3);
    }

    /**
     * Builds a detail line that mirrors the COBOL DTL-LINE structure:
     *
     *   DTL-ID       PIC 9(05)          → 5-digit zero-padded ID
     *   FILLER       PIC X(02) SPACES
     *   DTL-NAME     PIC X(20)          → left-justified, space-padded
     *   FILLER       PIC X(01) SPACES
     *   DTL-DEPT     PIC X(10)          → left-justified, space-padded
     *   FILLER       PIC X(01) SPACES
     *   DTL-SALARY   PIC Z,ZZZ,ZZ9.99  → right-justified, 10 chars
     *   FILLER       PIC X(03) SPACES
     *   DTL-HIRE-YYYY PIC 9(04)
     *   FILLER       PIC X "-"
     *   DTL-HIRE-MM  PIC 9(02)
     *   FILLER       PIC X "-"
     *   DTL-HIRE-DD  PIC 9(02)
     *   FILLER       PIC X(02) SPACES
     *   DTL-AGE      PIC Z9             → 2 chars, leading-zero suppressed
     *
     * Total: 5+2+20+1+10+1+10+3+4+1+2+1+2+2+2 = 66 chars (padded to 80).
     */
    public ReportLine detailLine(Employee emp) {
        String dtlId     = String.format("%05d", safe(emp.getEmpId()));
        String dtlName   = String.format("%-20s", nvl(emp.getEmpName()));
        String dtlDept   = String.format("%-10s", nvl(emp.getEmpDept()));
        String dtlSalary = formatSalary(emp.getEmpSalary());
        String dtlYyyy   = String.format("%04d", safe(emp.getEmpHireYyyy()));
        String dtlMm     = String.format("%02d", safe(emp.getEmpHireMm()));
        String dtlDd     = String.format("%02d", safe(emp.getEmpHireDD()));
        String dtlAge    = formatAge(emp.getEmpAge());

        String line = dtlId + "  " + dtlName + " " + dtlDept + " "
                + dtlSalary + "   "
                + dtlYyyy + "-" + dtlMm + "-" + dtlDd + "  "
                + dtlAge;

        return new ReportLine(line);
    }

    /**
     * Builds the trailer line mirroring TRL-LINE:
     *   FILLER PIC X(20) VALUE "TOTAL EMPLOYEES:"
     *   TRL-COUNT PIC ZZ9  → 3 chars, leading-zero suppressed
     */
    public ReportLine trailerLine(int count) {
        // PIC X(20) left-justifies the label
        String label = String.format("%-20s", "TOTAL EMPLOYEES:");
        // PIC ZZ9: suppress leading zeros for hundreds/tens, keep units
        String trlCount = formatZZ9(count);
        return new ReportLine(label + trlCount);
    }

    // ------------------------------------------------------------------
    // Private helpers
    // ------------------------------------------------------------------

    /**
     * COBOL PIC Z,ZZZ,ZZ9.99 – right-justify in 10 characters,
     * suppress leading zeros (replace with spaces), keep trailing decimals.
     */
    private String formatSalary(BigDecimal salary) {
        BigDecimal value = (salary == null) ? BigDecimal.ZERO : salary;
        String formatted = SALARY_FORMAT.format(value);  // e.g. "1,234.56"
        // Right-justify in 10 characters (Z,ZZZ,ZZ9.99 max = 10 digits + commas)
        return String.format("%10s", formatted);
    }

    /**
     * COBOL PIC Z9 – suppress leading zero for tens digit; units always shown.
     * Result is always 2 characters.
     */
    private String formatAge(Integer age) {
        int v = (age == null) ? 0 : age;
        // Z9: if tens digit is 0, replace with space
        int tens  = v / 10;
        int units = v % 10;
        char tensChar = (tens == 0) ? ' ' : (char) ('0' + tens);
        return String.valueOf(tensChar) + (char) ('0' + units);
    }

    /**
     * COBOL PIC ZZ9 – suppress leading zeros for hundreds and tens.
     * Result is always 3 characters.
     */
    private String formatZZ9(int value) {
        int hundreds = value / 100;
        int tens     = (value % 100) / 10;
        int units    = value % 10;
        char h = (hundreds == 0) ? ' ' : (char) ('0' + hundreds);
        char t = (hundreds == 0 && tens == 0) ? ' ' : (char) ('0' + tens);
        return String.valueOf(h) + t + (char) ('0' + units);
    }

    private int safe(Integer v) { return v == null ? 0 : v; }
    private String nvl(String v) { return v == null ? "" : v; }
}

