package com.example.emplist.service;

import com.example.emplist.entity.Employee;
import com.example.emplist.model.ReportLine;
import com.example.emplist.repository.EmployeeRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.io.BufferedWriter;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.List;

/**
 * Modernised equivalent of the COBOL EMPLIST program.
 *
 * Business logic preserved:
 *  1. Write HDR-1 (title)
 *  2. Write HDR-3 (dashes)
 *  3. Write HDR-2 (column headers)
 *  4. Write HDR-3 (dashes)
 *  5. For each employee (ordered by ID): write detail line, increment counter
 *  6. Write HDR-3 (dashes)
 *  7. Write trailer line with employee count
 *  8. Log record count to console (DISPLAY equivalent)
 */
@Service
public class EmplistService {

    private static final Logger log = LoggerFactory.getLogger(EmplistService.class);

    private final EmployeeRepository employeeRepository;
    private final ReportFormatterService formatter;

    @Value("${emplist.output.path:data/output/emplist.rpt}")
    private String outputPath;

    public EmplistService(EmployeeRepository employeeRepository,
                          ReportFormatterService formatter) {
        this.employeeRepository = employeeRepository;
        this.formatter = formatter;
    }

    /**
     * Executes the full EMPLIST report generation.
     *
     * @return the number of employee records listed (WS-COUNT equivalent)
     */
    @Transactional(readOnly = true)
    public int generateReport() {
        List<Employee> employees = employeeRepository.findAllOrderedById();

        Path reportPath = Paths.get(outputPath);
        try {
            Files.createDirectories(reportPath.getParent());
        } catch (IOException e) {
            throw new ReportGenerationException(
                    "Cannot create output directory: " + reportPath.getParent(), e);
        }

        int wsCount = 0;

        try (BufferedWriter writer = Files.newBufferedWriter(
                reportPath, StandardCharsets.UTF_8)) {

            // WRITE RPT-LINE FROM HDR-1
            writeLine(writer, formatter.header1());
            // WRITE RPT-LINE FROM HDR-3
            writeLine(writer, formatter.header3());
            // WRITE RPT-LINE FROM HDR-2
            writeLine(writer, formatter.header2());
            // WRITE RPT-LINE FROM HDR-3
            writeLine(writer, formatter.header3());

            // PERFORM UNTIL END-OF-FILE  →  iterate list (already fully loaded)
            for (Employee emp : employees) {
                // PERFORM WRITE-DETAIL
                wsCount++;                                      // ADD 1 TO WS-COUNT
                writeLine(writer, formatter.detailLine(emp));  // WRITE RPT-LINE FROM DTL-LINE
            }

            // WRITE RPT-LINE FROM HDR-3
            writeLine(writer, formatter.header3());
            // MOVE WS-COUNT TO TRL-COUNT  /  WRITE RPT-LINE FROM TRL-LINE
            writeLine(writer, formatter.trailerLine(wsCount));

        } catch (IOException e) {
            throw new ReportGenerationException(
                    "Error writing report file: " + reportPath, e);
        }

        // DISPLAY "EMPLIST: " WS-COUNT " RECORDS LISTED"
        log.info("EMPLIST: {} RECORDS LISTED", wsCount);

        return wsCount;
    }

    private void writeLine(BufferedWriter writer, ReportLine line) throws IOException {
        writer.write(line.getContent());
        writer.newLine();
    }
}

