package com.example.emplist.controller;

import com.example.emplist.service.EmplistService;
import com.example.emplist.service.ReportGenerationException;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.util.Map;

/**
 * REST entry-point that triggers the employee listing report.
 * POST /api/reports/emplist  →  generates the report and returns the record count.
 */
@RestController
@RequestMapping("/api/reports")
public class EmplistController {

    private final EmplistService emplistService;

    public EmplistController(EmplistService emplistService) {
        this.emplistService = emplistService;
    }

    @PostMapping("/emplist")
    public ResponseEntity<Map<String, Object>> generateEmplist() {
        try {
            int count = emplistService.generateReport();
            return ResponseEntity.ok(Map.of(
                    "status",       "SUCCESS",
                    "recordsListed", count,
                    "message",      "EMPLIST: " + count + " RECORDS LISTED"
            ));
        } catch (ReportGenerationException ex) {
            return ResponseEntity.internalServerError().body(Map.of(
                    "status",  "ERROR",
                    "message", ex.getMessage()
            ));
        }
    }
}

