package com.example.emplist.runner;

import com.example.emplist.service.EmplistService;
import org.springframework.boot.CommandLineRunner;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.stereotype.Component;

/**
 * Optional batch runner: when emplist.run-on-startup=true the report is
 * generated automatically at boot, mimicking the original STOP RUN behaviour.
 */
@Component
@ConditionalOnProperty(name = "emplist.run-on-startup", havingValue = "true")
public class EmplistRunner implements CommandLineRunner {

    private final EmplistService emplistService;

    public EmplistRunner(EmplistService emplistService) {
        this.emplistService = emplistService;
    }

    @Override
    public void run(String... args) {
        emplistService.generateReport();
    }
}

