package com.example.emplist.service;

import com.example.emplist.entity.Employee;
import com.example.emplist.model.ReportLine;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import java.math.BigDecimal;

import static org.junit.jupiter.api.Assertions.*;

class ReportFormatterServiceTest {

    private ReportFormatterService formatter;

    @BeforeEach
    void setUp() {
        formatter = new ReportFormatterService();
    }

    @Test
    void header3IsSixtyDashes() {
        ReportLine h3 = formatter.header3();
        // Padded to 80 chars; first 80 chars are dashes
        assertTrue(h3.getContent().startsWith("-".repeat(80)));
    }

    @Test
    void detailLineIsExactly80Chars() {
        Employee e = buildEmployee(1, "John Smith", "SALES",
                new BigDecimal("45000.00"), 2010, 3, 15, 35);
        ReportLine line = formatter.detailLine(e);
        assertEquals(80, line.getContent().length());
    }

    @Test
    void detailLineContainsFormattedSalary() {
        Employee e = buildEmployee(2, "Jane Doe", "HR",
                new BigDecimal("1234567.89"), 2015, 7, 22, 42);
        String content = formatter.detailLine(e).getContent();
        assertTrue(content.contains("1,234,567.89"),
                "Expected formatted salary in: " + content);
    }

    @Test
    void trailerLineShowsCount() {
        ReportLine trl = formatter.trailerLine(42);
        String content = trl.getContent();
        assertTrue(content.startsWith("TOTAL EMPLOYEES:    "));
        // ZZ9 of 42 → " 42"
        assertTrue(content.contains(" 42"), "content: " + content);
    }

    @Test
    void ageFormatZ9() {
        // Age 5  → " 5" ; Age 35 → "35"
        Employee e5  = buildEmployee(3, "A", "X", BigDecimal.ZERO, 2000, 1, 1, 5);
        Employee e35 = buildEmployee(4, "B", "Y", BigDecimal.ZERO, 2000, 1, 1, 35);
        String line5  = formatter.detailLine(e5).getContent();
        String line35 = formatter.detailLine(e35).getContent();
        // Age occupies the last 2 chars of the 66-char formatted section
        assertTrue(line5.contains(" 5"),  "line5: "  + line5);
        assertTrue(line35.contains("35"), "line35: " + line35);
    }

    private Employee buildEmployee(int id, String name, String dept,
                                   BigDecimal salary,
                                   int yyyy, int mm, int dd, int age) {
        Employee e = new Employee();
        e.setEmpId(id);
        e.setEmpName(name);
        e.setEmpDept(dept);
        e.setEmpSalary(salary);
        e.setEmpHireYyyy(yyyy);
        e.setEmpHireMm(mm);
        e.setEmpHireDD(dd);
        e.setEmpAge(age);
        return e;
    }
}
